        {"text": "Зелье воскрешения жреца вуду", "action": "revive", "description": "Дымный ритуал возвращает выбывшего игрока в строй."},
        {"text": "Помилование в последний миг", "action": "revive", "description": "Веревка обрывается, и изгнанный возвращается к столу."},
        {"text": "Ночной побег из карцера", "action": "revive", "description": "Вы отпираете замок и возвращаете изгнанного соратника."},
        {"text": "Двойное дно спасательной шлюпки", "action": "revive", "description": "Оказывается, изгнанный спрятался под брезентом и снова с вами."},

        {"text": "Яд кураре в кружке рома", "action": "poison", "description": "Подлить яд в ром цели: добавляет скрытый голос против нее."},
        {"text": "Проклятие черного дублона", "action": "poison", "description": "Подброшенная проклятая монета добавляет +1 голос против цели."},
        {"text": "Смертоносная игла морского ската", "action": "poison", "description": "Коварный укол: выбранный игрок получает дополнительный голос против себя."},
        {"text": "Тайный донос капитану", "action": "poison", "description": "Вы шепчете о заговоре — цель получает +1 штрафной голос."},
        {"text": "Подброшенная черная метка", "action": "poison", "description": "В кармане цели находят метку: +1 голос против нее на совете."},
        {"text": "Протухшая солонина в миске", "action": "poison", "description": "Ослабленный отравлением игрок получает +1 голос против себя."},
        {"text": "Порча от куклы вуду", "action": "poison", "description": "Укол иголкой в куклу приносит цели дополнительный голос против."},
        {"text": "Оклеветать перед боцманом", "action": "poison", "description": "Боцман зол на цель: +1 голос против нее на этом голосовании."},
        {"text": "Песок в кремневом замке врага", "action": "poison", "description": "Беспомощный в бою игрок получает +1 голос против на совете."},
        {"text": "Фальшивые дублоны в чужом рундуке", "action": "poison", "description": "Команда подозревает цель в воровстве (+1 голос против нее)."},
        {"text": "Разбитая склянка с приманкой для акул", "action": "poison", "description": "От цели несет кровью — +1 голос против нее на голосовании."},
        {"text": "Подпиленная перекладина гамака", "action": "poison", "description": "Невыспавшийся и злой игрок раздражает всех (+1 голос против)."},
        {"text": "Зараженный ром из трюма", "action": "poison", "description": "Цель бредит на совете и получает +1 голос против себя."},
        {"text": "Соляной сглаз морской ведьмы", "action": "poison", "description": "Проклятая соль на пороге приносит цели +1 голос против нее на совете."},
